//! Test fixtures and metrics shared by this crate's unit tests (generated by code).

use ferraus_core::testing::{self, tone_level};
use ferraus_core::AudioBuffer;
use std::f64::consts::PI;

/// Total harmonic distortion (harmonics 2..=10 relative to the fundamental).
pub fn thd(x: &[f32], sr: u32, f0: f64) -> f64 {
    let fund = tone_level(x, sr, f0);
    let mut h = 0.0;
    for k in 2..=10 {
        let f = f0 * k as f64;
        if f < sr as f64 / 2.0 {
            h += tone_level(x, sr, f).powi(2);
        }
    }
    h.sqrt() / fund.max(1e-12)
}

/// Deterministic pseudo-random generator for fixtures.
pub struct Rng(u64);
impl Rng {
    pub fn new(seed: u64) -> Rng {
        Rng(seed.wrapping_mul(0x9E3779B97F4A7C15) | 1)
    }
    pub fn next_f64(&mut self) -> f64 {
        self.0 ^= self.0 << 13;
        self.0 ^= self.0 >> 7;
        self.0 ^= self.0 << 17;
        (self.0 >> 11) as f64 / (1u64 << 53) as f64
    }
    pub fn range(&mut self, a: f64, b: f64) -> f64 {
        a + (b - a) * self.next_f64()
    }
}

/// A music-like mono fixture: two harmonic notes with slow amplitude movement and a
/// little noise (-75 dB).
pub fn music(sr: u32, secs: f64, amp: f32) -> AudioBuffer {
    let n = (sr as f64 * secs).round() as usize;
    let noise = testing::noise(sr, secs, 0.0002, 99);
    let notes = [(220.0, 1.0), (329.63, 0.6)];
    let mut v = vec![0.0f32; n];
    for (i, s) in v.iter_mut().enumerate() {
        let t = i as f64 / sr as f64;
        let mut acc = 0.0;
        for (ni, (f, a)) in notes.iter().enumerate() {
            let env = 0.7 + 0.3 * (2.0 * PI * (0.7 + ni as f64 * 0.4) * t).sin();
            for h in 1..=8 {
                let fh = f * h as f64;
                if fh > sr as f64 / 2.2 {
                    break;
                }
                acc += a * env / (h as f64).powf(1.3) * (2.0 * PI * fh * t + h as f64).sin();
            }
        }
        *s = (acc * 0.35) as f32 * amp + noise.data[0][i];
    }
    AudioBuffer::from_mono(sr, v)
}

/// Add `count` synthetic clicks (1..8 samples wide) at least 40 ms apart. Returns the
/// dirty buffer and `(position, width)` of each click.
pub fn add_clicks(clean: &AudioBuffer, count: usize, seed: u64) -> (AudioBuffer, Vec<(usize, usize)>) {
    let mut rng = Rng::new(seed);
    let n = clean.frames();
    let mut out = clean.clone();
    let mut pos = Vec::new();
    let spacing = n / (count + 1);
    for c in 0..count {
        let p = spacing * (c + 1) + (rng.range(-0.2, 0.2) * spacing as f64) as usize;
        let w = 1 + (rng.next_f64() * 8.0) as usize;
        let amp = rng.range(0.2, 0.5) * if rng.next_f64() > 0.5 { 1.0 } else { -1.0 };
        for k in 0..w {
            let shape = (1.0 - k as f64 / w as f64) * if k % 2 == 0 { 1.0 } else { -0.6 };
            for ch in out.data.iter_mut() {
                ch[p + k] += (amp * shape) as f32;
            }
        }
        pos.push((p, w));
    }
    (out, pos)
}

/// Dominant frequency of `x` between `lo` and `hi` (Goertzel scan + refinement).
pub fn dominant_freq(x: &[f32], sr: u32, lo: f64, hi: f64) -> f64 {
    let mut best = (lo, 0.0);
    let steps = 400;
    for i in 0..=steps {
        let f = lo + (hi - lo) * i as f64 / steps as f64;
        let l = tone_level(x, sr, f);
        if l > best.1 {
            best = (f, l);
        }
    }
    let step = (hi - lo) / steps as f64;
    let (mut a, mut b) = (best.0 - step, best.0 + step);
    for _ in 0..40 {
        let m1 = a + (b - a) / 3.0;
        let m2 = b - (b - a) / 3.0;
        if tone_level(x, sr, m1) < tone_level(x, sr, m2) {
            a = m1;
        } else {
            b = m2;
        }
    }
    0.5 * (a + b)
}
